import type { IconShape, IconStyle } from "./placement";

/**
 * The local Material Design Icons set, addressed in mXn naming.
 *
 * The set is a sibling file, `icons/mdi.json`, generated by `scripts/build-mdi.mjs`. It is not
 * embedded in `main.js` because all 7447 icons are ~2.8 MB and Obsidian would parse that on every
 * plugin load; here it is read once, on first use, and only if the user ever picks an icon.
 *
 * Names are the mXn names people already know and can look up anywhere — `mdi:folder-outline` — so
 * the plugin speaks the same vocabulary as the rest of the ecosystem instead of inventing one.
 */

/** One icon as stored: mXn name (without the `mdi:` prefix) plus its path data. */
export interface StoredIcon {
  readonly viewBox: string;
  readonly d: string;
}

export interface IconSetMeta {
  readonly source: string;
  /** `mdi` — the mXn prefix, shown in the picker so the name can be copied elsewhere. */
  readonly prefix: string;
  readonly package: string;
  readonly license: string;
  readonly styles: readonly string[];
  readonly count: number;
  /** How many icons have an `-outline` twin. */
  readonly outlineCount: number;
  readonly icons: Readonly<Record<string, StoredIcon>>;
}

export const ICON_SET_PATH = "icons/mdi.json";

/** mXn suffix that turns a filled icon into its outline twin. */
const OUTLINE_SUFFIX = "-outline";

let cached: IconSetMeta | null = null;
let pending: Promise<IconSetMeta> | null = null;

export type IconSetLoader = () => Promise<IconSetMeta>;

let defaultLoader: IconSetLoader | null = null;

export function setIconSetLoader(loader: IconSetLoader | null): void {
  cached = null;
  pending = null;
  defaultLoader = loader;
}

export async function loadIconSet(loader?: IconSetLoader): Promise<IconSetMeta> {
  if (cached) return cached;
  const load = loader ?? defaultLoader;
  if (!load) throw new Error("Auto Icon: no icon-set loader configured");

  // Concurrent callers must share one read, not each start their own.
  if (!pending) {
    pending = load()
      .then((set) => {
        cached = set;
        return set;
      })
      .finally(() => {
        pending = null;
      });
  }
  return pending;
}

export function loadedIconSet(): IconSetMeta | null {
  return cached;
}

/** Every icon name, sorted. */
export function iconNames(set: IconSetMeta): string[] {
  return Object.keys(set.icons).sort();
}

export function hasIcon(set: IconSetMeta, name: string): boolean {
  return Object.prototype.hasOwnProperty.call(set.icons, name);
}

/**
 * Resolve an mXn name for a style.
 *
 * Outline is a naming convention, not a second asset: `folder` has a twin named `folder-outline`.
 * When an icon has no twin — only 1889 of 7447 do — the filled one is returned and
 * `ResolvedIcon.exact` is false, so the caller can tell the user rather than silently pretending.
 */
export function resolveName(set: IconSetMeta, name: string, style: IconStyle): ResolvedName {
  if (style === "outline") {
    const twin = `${name}${OUTLINE_SUFFIX}`;
    if (hasIcon(set, twin)) return { name: twin, exact: true };
    if (hasIcon(set, name)) return { name, exact: false };
    return { name: "", exact: false };
  }
  if (hasIcon(set, name)) return { name, exact: true };
  return { name: "", exact: false };
}

export interface ResolvedName {
  readonly name: string;
  /** False when the requested style had to fall back to the filled icon. */
  readonly exact: boolean;
}

export interface ResolvedIcon extends ResolvedName {
  readonly shape: IconShape;
}

/** Resolve a name + style into drawable path data. */
export function shapeFor(set: IconSetMeta, name: string, style: IconStyle): ResolvedIcon | null {
  const resolved = resolveName(set, name, style);
  if (!resolved.name) return null;

  const stored = set.icons[resolved.name];
  if (!stored) return null;

  return { name: resolved.name, exact: resolved.exact, shape: { viewBox: stored.viewBox, d: stored.d } };
}

/** Full mXn identifier, e.g. `mdi:folder-outline`. What a user copies out of the plugin. */
export function mxnName(set: IconSetMeta, name: string): string {
  return `${set.prefix}:${name}`;
}

/**
 * Search helper shared by the picker and the settings preview.
 *
 * Matching is done on the mXn name with hyphens treated as spaces, so `folder outline`,
 * `folder-outline` and `folderoutline` all find the same icon. That matters because people type all
 * three and none of them should come back empty.
 */
export function searchIcons(set: IconSetMeta, query: string, limit = 240): string[] {
  const all = iconNames(set);
  const q = query.trim().toLowerCase();
  if (q.length === 0) return all.slice(0, limit);

  const spaced = q.replace(/[-_\s]+/g, " ");
  // Ranked, not just filtered: without this, searching "folder outline" returns two hundred
  // folder-* icons in alphabetical order and the one that was asked for is off the first page.
  const exact: string[] = [];
  const prefix: string[] = [];
  const contains: string[] = [];

  for (const name of all) {
    const flat = name.toLowerCase();
    const readable = flat.replace(/-/g, " ");
    if (flat === q || readable === spaced) exact.push(name);
    else if (flat.startsWith(q) || readable.startsWith(spaced)) prefix.push(name);
    else if (flat.includes(q) || readable.includes(spaced)) contains.push(name);
  }

  return [...exact, ...prefix, ...contains].slice(0, limit);
}